package com.onlinelearning.security;
import io.jsonwebtoken.Jwts; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import javax.crypto.SecretKey; import java.nio.charset.StandardCharsets; import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final long expiration; public JwtService(@Value("${app.jwt.secret}")String s,@Value("${app.jwt.expiration}")long e){key=Keys.hmacShaKeyFor(s.getBytes(StandardCharsets.UTF_8));expiration=e;} public String generate(String u,String r){Date n=new Date();return Jwts.builder().subject(u).claim("role",r).issuedAt(n).expiration(new Date(n.getTime()+expiration)).signWith(key).compact();} public String username(String t){return Jwts.parser().verifyWith(key).build().parseSignedClaims(t).getPayload().getSubject();} }